  bool access::object_traits_impl< ::suiDataSql::suiFileMeta, id_mysql >::
  grow (image_type& i,
        my_bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // _primaryKey
    //
    t[0UL] = 0;

    // _file_id
    //
    if (t[1UL])
    {
      i._file_id_value.capacity (i._file_id_size);
      grew = true;
    }

    // _upload_user_id
    //
    if (t[2UL])
    {
      i._upload_user_id_value.capacity (i._upload_user_id_size);
      grew = true;
    }

    // _path
    //
    if (t[3UL])
    {
      i._path_value.capacity (i._path_size);
      grew = true;
    }

    // _size
    //
    t[4UL] = 0;

    // _mime_type
    //
    if (t[5UL])
    {
      i._mime_type_value.capacity (i._mime_type_size);
      grew = true;
    }

    // _upload_time
    //
    t[6UL] = 0;

    // _file_status
    //
    t[7UL] = 0;

    return grew;
  }

