  bool access::object_traits_impl< ::suiDataSql::suiIdentityMeta, id_mysql >::
  grow (image_type& i,
        my_bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // _primaryKey
    //
    t[0UL] = 0;

    // _identity_id
    //
    if (t[1UL])
    {
      i._identity_id_value.capacity (i._identity_id_size);
      grew = true;
    }

    // _identityType
    //
    t[2UL] = 0;

    // _identity_description
    //
    if (t[3UL])
    {
      i._identity_description_value.capacity (i._identity_description_size);
      grew = true;
    }

    return grew;
  }

  void access::object_traits_impl< ::suiDataSql::suiIdentityMeta, id_mysql >::
  bind (MYSQL_BIND* b,
        image_type& i,
        mysql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace mysql;

    std::size_t n (0);

    // _primaryKey
    //
    if (sk != statement_update)
    {
      b[n].buffer_type = MYSQL_TYPE_LONGLONG;
      b[n].is_unsigned = 1;
      b[n].buffer = &i._primaryKey_value;
      b[n].is_null = &i._primaryKey_null;
      n++;
    }

    // _identity_id
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._identity_id_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._identity_id_value.capacity ());
    b[n].length = &i._identity_id_size;
    b[n].is_null = &i._identity_id_null;
    n++;

    // _identityType
    //
    b[n].buffer_type = MYSQL_TYPE_TINY;
    b[n].is_unsigned = 1;
    b[n].buffer = &i._identityType_value;
    b[n].is_null = &i._identityType_null;
    n++;

    // _identity_description
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._identity_description_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._identity_description_value.capacity ());
    b[n].length = &i._identity_description_size;
    b[n].is_null = &i._identity_description_null;
    n++;
  }

  void access::object_traits_impl< ::suiDataSql::suiIdentityMeta, id_mysql >::
  bind (MYSQL_BIND* b, id_image_type& i)
  {
    std::size_t n (0);
    b[n].buffer_type = MYSQL_TYPE_LONGLONG;
    b[n].is_unsigned = 1;
    b[n].buffer = &i.id_value;
    b[n].is_null = &i.id_null;
  }

  bool access::object_traits_impl< ::suiDataSql::suiIdentityMeta, id_mysql >::
  init (image_type& i,
        const object_type& o,
        mysql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (o);
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace mysql;

    bool grew (false);

    // _primaryKey
    //
    if (sk == statement_insert)
    {
      long long unsigned int const& v =
        o._primaryKey;

      bool is_null (false);
      mysql::value_traits<
          long long unsigned int,
          mysql::id_ulonglong >::set_image (
        i._primaryKey_value, is_null, v);
      i._primaryKey_null = is_null;
    }

    // _identity_id
    //
    {
      ::std::string const& v =
        o._identity_id;

      bool is_null (false);
      std::size_t size (0);
      std::size_t cap (i._identity_id_value.capacity ());
      mysql::value_traits<
          ::std::string,
          mysql::id_string >::set_image (
        i._identity_id_value,
        size,
        is_null,
        v);
      i._identity_id_null = is_null;
      i._identity_id_size = static_cast<unsigned long> (size);
      grew = grew || (cap != i._identity_id_value.capacity ());
    }

    // _identityType
    //
    {
      ::suiDataSql::identityType const& v =
        o._identityType;

      bool is_null (false);
      mysql::value_traits<
          ::suiDataSql::identityType,
          mysql::id_utiny >::set_image (
        i._identityType_value, is_null, v);
      i._identityType_null = is_null;
    }

    // _identity_description
    //
    {
      ::odb::nullable< ::std::basic_string< char > > const& v =
        o._identity_description;

      bool is_null (true);
      std::size_t size (0);
      std::size_t cap (i._identity_description_value.capacity ());
      mysql::value_traits<
          ::odb::nullable< ::std::basic_string< char > >,
          mysql::id_string >::set_image (
        i._identity_description_value,
        size,
        is_null,
        v);
      i._identity_description_null = is_null;
      i._identity_description_size = static_cast<unsigned long> (size);
      grew = grew || (cap != i._identity_description_value.capacity ());
    }

    return grew;
  }

