  bool access::object_traits_impl< ::suiDataSql::suiOperationMeta, id_mysql >::
  grow (image_type& i,
        my_bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // _primaryKey
    //
    t[0UL] = 0;

    // _operation_id
    //
    if (t[1UL])
    {
      i._operation_id_value.capacity (i._operation_id_size);
      grew = true;
    }

    // _operation_url
    //
    if (t[2UL])
    {
      i._operation_url_value.capacity (i._operation_url_size);
      grew = true;
    }

    // _operation_description
    //
    if (t[3UL])
    {
      i._operation_description_value.capacity (i._operation_description_size);
      grew = true;
    }

    return grew;
  }

  void access::object_traits_impl< ::suiDataSql::suiOperationMeta, id_mysql >::
  bind (MYSQL_BIND* b,
        image_type& i,
        mysql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace mysql;

    std::size_t n (0);

    // _primaryKey
    //
    if (sk != statement_update)
    {
      b[n].buffer_type = MYSQL_TYPE_LONGLONG;
      b[n].is_unsigned = 1;
      b[n].buffer = &i._primaryKey_value;
      b[n].is_null = &i._primaryKey_null;
      n++;
    }

    // _operation_id
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._operation_id_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._operation_id_value.capacity ());
    b[n].length = &i._operation_id_size;
    b[n].is_null = &i._operation_id_null;
    n++;

    // _operation_url
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._operation_url_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._operation_url_value.capacity ());
    b[n].length = &i._operation_url_size;
    b[n].is_null = &i._operation_url_null;
    n++;

    // _operation_description
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._operation_description_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._operation_description_value.capacity ());
    b[n].length = &i._operation_description_size;
    b[n].is_null = &i._operation_description_null;
    n++;
  }

