  bool access::object_traits_impl< ::suiDataSql::suiVideoMeta, id_mysql >::
  grow (image_type& i,
        my_bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // _primaryKey
    //
    t[0UL] = 0;

    // _video_id
    //
    if (t[1UL])
    {
      i._video_id_value.capacity (i._video_id_size);
      grew = true;
    }

    // _video_file_id
    //
    if (t[2UL])
    {
      i._video_file_id_value.capacity (i._video_file_id_size);
      grew = true;
    }

    // _video_cover_file_id
    //
    if (t[3UL])
    {
      i._video_cover_file_id_value.capacity (i._video_cover_file_id_size);
      grew = true;
    }

    // _upload_user_id
    //
    if (t[4UL])
    {
      i._upload_user_id_value.capacity (i._upload_user_id_size);
      grew = true;
    }

    // _review_user_id
    //
    if (t[5UL])
    {
      i._review_user_id_value.capacity (i._review_user_id_size);
      grew = true;
    }

    // _video_name
    //
    if (t[6UL])
    {
      i._video_name_value.capacity (i._video_name_size);
      grew = true;
    }

    // _video_description
    //
    if (t[7UL])
    {
      i._video_description_value.capacity (i._video_description_size);
      grew = true;
    }

    // _video_play_count
    //
    t[8UL] = 0;

    // _video_size
    //
    t[9UL] = 0;

    // _video_duration
    //
    t[10UL] = 0;

    // _video_upload_time
    //
    t[11UL] = 0;

    // _video_status
    //
    t[12UL] = 0;

    return grew;
  }

