  bool access::object_traits_impl< ::suiDataSql::suiUserLikeMeta, id_mysql >::
  grow (image_type& i,
        my_bool* t)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (t);

    bool grew (false);

    // _primaryKey
    //
    t[0UL] = 0;

    // _user_id
    //
    if (t[1UL])
    {
      i._user_id_value.capacity (i._user_id_size);
      grew = true;
    }

    // _video_id
    //
    if (t[2UL])
    {
      i._video_id_value.capacity (i._video_id_size);
      grew = true;
    }

    return grew;
  }

  void access::object_traits_impl< ::suiDataSql::suiUserLikeMeta, id_mysql >::
  bind (MYSQL_BIND* b,
        image_type& i,
        mysql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace mysql;

    std::size_t n (0);

    // _primaryKey
    //
    if (sk != statement_update)
    {
      b[n].buffer_type = MYSQL_TYPE_LONGLONG;
      b[n].is_unsigned = 1;
      b[n].buffer = &i._primaryKey_value;
      b[n].is_null = &i._primaryKey_null;
      n++;
    }

    // _user_id
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._user_id_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._user_id_value.capacity ());
    b[n].length = &i._user_id_size;
    b[n].is_null = &i._user_id_null;
    n++;

    // _video_id
    //
    b[n].buffer_type = MYSQL_TYPE_STRING;
    b[n].buffer = i._video_id_value.data ();
    b[n].buffer_length = static_cast<unsigned long> (
      i._video_id_value.capacity ());
    b[n].length = &i._video_id_size;
    b[n].is_null = &i._video_id_null;
    n++;
  }

  void access::object_traits_impl< ::suiDataSql::suiUserLikeMeta, id_mysql >::
  bind (MYSQL_BIND* b, id_image_type& i)
  {
    std::size_t n (0);
    b[n].buffer_type = MYSQL_TYPE_LONGLONG;
    b[n].is_unsigned = 1;
    b[n].buffer = &i.id_value;
    b[n].is_null = &i.id_null;
  }

  bool access::object_traits_impl< ::suiDataSql::suiUserLikeMeta, id_mysql >::
  init (image_type& i,
        const object_type& o,
        mysql::statement_kind sk)
  {
    ODB_POTENTIALLY_UNUSED (i);
    ODB_POTENTIALLY_UNUSED (o);
    ODB_POTENTIALLY_UNUSED (sk);

    using namespace mysql;

    bool grew (false);

    // _primaryKey
    //
    if (sk == statement_insert)
    {
      long long unsigned int const& v =
        o._primaryKey;

      bool is_null (false);
      mysql::value_traits<
          long long unsigned int,
          mysql::id_ulonglong >::set_image (
        i._primaryKey_value, is_null, v);
      i._primaryKey_null = is_null;
    }

    // _user_id
    //
    {
      ::std::string const& v =
        o._user_id;

      bool is_null (false);
      std::size_t size (0);
      std::size_t cap (i._user_id_value.capacity ());
      mysql::value_traits<
          ::std::string,
          mysql::id_string >::set_image (
        i._user_id_value,
        size,
        is_null,
        v);
      i._user_id_null = is_null;
      i._user_id_size = static_cast<unsigned long> (size);
      grew = grew || (cap != i._user_id_value.capacity ());
    }

    // _video_id
    //
    {
      ::std::string const& v =
        o._video_id;

      bool is_null (false);
      std::size_t size (0);
      std::size_t cap (i._video_id_value.capacity ());
      mysql::value_traits<
          ::std::string,
          mysql::id_string >::set_image (
        i._video_id_value,
        size,
        is_null,
        v);
      i._video_id_null = is_null;
      i._video_id_size = static_cast<unsigned long> (size);
      grew = grew || (cap != i._video_id_value.capacity ());
    }

    return grew;
  }

